def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and not seen[r][c]:
                col=g[r][c]; st=[(r,c)]; cells=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]:continue
                    seen[y][x]=True; cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col: st.append((ny,nx))
                out.append((col,cells))
    return out
def solve(inp, axis):
    # axis: 'up' or 'down' or 'left' or 'right'; anchor = color 2 line
    H,W=len(inp),len(inp[0])
    g=[row[:] for row in inp]
    anchor_cells=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==2]
    ar={r for r,_ in anchor_cells}; ac={c for _,c in anchor_cells}
    if axis=='up': blocked=lambda r: any(r2<r for r2,_ in anchor_cells) or False
    def anchor_in_path(r,c):
        if axis=='up': return any(rr==r for rr,cc in anchor_cells) and cc==c  # approximate
    objs=comps(inp)
    # move each object toward anchor along its axis until blocked by anchor or another object
    moved=True
    while moved:
        moved=False
        for col,cells in objs:
            rs=[r for r,_ in cells]; cs=[c for _,c in cells]
            dr=1 if axis in ('up','down') else 0
            dc=-1 if axis=='left' else 1
            ok=True
            nr=max(rs+dr) if axis in('up','down') else max(cs+dc)
            nc=min(cs+dc) if axis in('up','down') else min(rs+dr)
            if axis in('up','down'):
                # blocked if anchor row reached or overlap with settled objects
                cand={(r+dr,c) for r,c in cells}
                if any((r,c) in anchor_cells or (r,c) in {(a,b) for a,b in set().union(*[(set(c2) for c2 in [cc for cc in []])])} for r,c in cand): ok=False
                # simpler: blocked if any candidate cell is anchor or occupied by another object's cells
                occ=set().union(*[c2 for c2 in [[c for r,c in o2[1]] for o2 in objs if o2[0]!=col]]) if len(objs)>1 else set()
                if any((r+dr,c) in anchor_cells or (r+dr,c) in occ for r,c in cells): ok=False
            else:
                cand={(r,c+dc) for r,c in cells}
                occ={(r,c) for r,c in [(a,b) for (ca,cb) in objs if ca!=col for a,b in cb]} if len(objs)>1 else set()
                if any((r,c+dc) in anchor_cells or (r,c+dc) in occ for r,c in cells): ok=False
            if ok:
                for r,c in cells: g[r][c]=0
                for r,c in cells: g[r+dr][c+dc]=col if axis in('up','down') else g[r][c+dc]=col
                moved=True
    return g
